import AppKit
import XCTest

/// The app icon asset catalog (generated by scripts/make-app-icon.sh from assets/icon/icon.PNG).
final class AppIconTests: XCTestCase {
    private let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
    private var iconSet: URL { root.appendingPathComponent("Assets.xcassets/AppIcon.appiconset") }

    private struct Contents: Decodable {
        struct Image: Decodable { let filename: String?; let idiom: String; let scale: String; let size: String }
        let images: [Image]
    }

    func testEveryMacSizeIsPresentAtTheRightResolution() throws {
        let contents = try JSONDecoder().decode(Contents.self, from: Data(contentsOf: iconSet.appendingPathComponent("Contents.json")))
        let expected = Set(["16x16@1x", "16x16@2x", "32x32@1x", "32x32@2x", "128x128@1x", "128x128@2x",
                            "256x256@1x", "256x256@2x", "512x512@1x", "512x512@2x"])
        XCTAssertEqual(Set(contents.images.map { "\($0.size)@\($0.scale)" }), expected)
        for image in contents.images {
            XCTAssertEqual(image.idiom, "mac")
            let file = try XCTUnwrap(image.filename, "\(image.size)@\(image.scale) has no file")
            let rep = try XCTUnwrap(NSBitmapImageRep(data: Data(contentsOf: iconSet.appendingPathComponent(file))), file)
            let points = Int(image.size.split(separator: "x")[0])!
            let scale = Int(image.scale.dropLast())!
            XCTAssertEqual(rep.pixelsWide, points * scale, file)
            XCTAssertEqual(rep.pixelsHigh, points * scale, file)
            XCTAssertTrue(rep.hasAlpha, "\(file) lost its transparency")
            XCTAssertEqual(rep.colorAt(x: 0, y: 0)?.alphaComponent, 0, "\(file): the corners must stay transparent")
        }
    }

    func testLargestRepresentationIsTheUnmodifiedMaster() throws {
        let master = root.deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent("assets/icon/icon.PNG")
        XCTAssertEqual(try Data(contentsOf: iconSet.appendingPathComponent("icon_512x512@2x.png")), try Data(contentsOf: master))
    }
}
